/**
 * Represents the user's UI and system preferences.
 */
interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

/**
 * Represents the core User data structure.
 */
interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string; // ISO 8601 format
  metadata: Record<string, any> | null;
}

/**
 * Validates the User object at runtime against the inferred schema.
 * @param user The object to validate.
 * @returns boolean indicating if the object matches the schema.
 * @throws Error if validation fails (optional implementation choice).
 */
function validateUser(user: any): boolean {
  try {
    // 1. Basic type checks for top-level properties
    if (!Number.isInteger(user.id)) throw new Error("Invalid id");

    if (typeof user.name !== "string" || user.name.length === 0) {
      throw new Error("Invalid name");
    }

    if (typeof user.email !== "string" || !user.email.includes("@")) {
      throw new Error("Invalid email");
    }

    // 2. Preferences sub-interface validation
    if (!user.preferences || typeof user.preferences !== "object") {
      throw new Error("Missing preferences");
    }
    if (typeof user.preferences.theme !== "string") {
      throw new Error("Invalid theme");
    }
    if (typeof user.preferences.notifications !== "boolean") {
      throw new Error("Invalid notifications setting");
    }

    // 3. Tags array validation
    if (!Array.isArray(user.tags) || !user.tags.every((t: any) => typeof t === "string")) {
      throw new Error("Tags must be an array of strings");
    }

    // 4. Metadata validation (nullable/optional handling)
    if (user.metadata !== null && typeof user.metadata !== "object") {
      throw new Error("Metadata must be an object or null");
    }

    // 5. Date string validation
    if (typeof user.last_login !== "string") {
      throw new Error("Invalid last_login format");
    }

    return true;
  } catch (e) {
    console.error("Validation failed:", e.message);
    return false;
  }
}

