  "id": 12345,
  "name": "Alice",
  "email": "alice@example.com",
  "preferences": {
    "theme": "dark",
    "notifications": true,
    "language": "en"
  },
  "tags": ["admin", "beta-tester"],
  "last_login": "2024-01-15T10:30:00Z",
  "metadata": null
};

console.log("Is user valid?", validateUser(user)); // Expected: true
